/**
 * A rectangle in a {@link BasesTableView}'s coordinates, in pixels.
 *
 * @public
 * @unofficial
 */
export interface BasesTableRect {
  /** The bottom edge. */
  bottom: number;

  /** The left edge. */
  left: number;

  /** The right edge. */
  right: number;

  /** The top edge. */
  top: number;
}
